//! Compare registry factory slice to retained scripted source rows.
use spore_core::cell_provider_registry_factory_v1::{project,Action};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let p=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(p).unwrap();assert_eq!(b.len(),192);for i in 0..6{let kind=i%3;let cw=if i>=3{0x37f}else{0x27f};let factory=match kind{0=>None,1=>Some(None),_=>Some(Some(1))};let x=project(kind==0,Some(2),0x12345678,factory,cw,0x1f80,true).unwrap();let row=&b[i*32..(i+1)*32];assert_eq!(w(row,0),x.slot.unwrap_or(0));assert_eq!(w(row,4),1);let miss=u32::from(kind!=0);assert_eq!(w(row,8),miss);assert_eq!(w(row,12),miss);assert_eq!(w(row,16),1-miss);if kind==0{assert_eq!(x.actions,vec![Action::InnerLookup,Action::HitPending]);}else{assert_eq!(x.actions,vec![Action::InnerLookup,Action::Factory{key:0x12345678,type_id:0x0179c807},Action::Store(x.slot)]);}let fp=w(row,20);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,24)&!0x3f,0x1f80);assert_eq!(w(row,28),i as u32);}println!("matched 6 retained registry lookup/factory rows; callbacks scripted");}
